<?php session_start(); require 'conectare.php'; include 'page_top.php'; include 'meniu.php';
$newBooks=$pdo->query('SELECT c.id_carte,c.titlu,a.nume_autor,c.pret FROM carti c JOIN autori a ON a.id_autor=c.id_autor ORDER BY c.data DESC LIMIT 6')->fetchAll();
$popular=$pdo->query('SELECT c.id_carte,c.titlu,a.nume_autor,c.pret,COALESCE(SUM(v.nr_buc),0) vandute FROM carti c JOIN autori a ON a.id_autor=c.id_autor LEFT JOIN vanzari v ON v.id_carte=c.id_carte GROUP BY c.id_carte,c.titlu,a.nume_autor,c.pret ORDER BY vandute DESC,c.titlu LIMIT 6')->fetchAll();
function card(array $b):void{$id=(int)$b['id_carte'];$img="./coperti/$id.jpg";echo '<article class="book-card"><a href="carte.php?id_carte='.$id.'">';if(file_exists($img))echo '<img class="cover" src="'.h($img).'" alt="">';else echo '<div class="cover-placeholder">'.h($b['titlu']).'</div>';echo '</a><h3 class="book-title"><a href="carte.php?id_carte='.$id.'">'.h($b['titlu']).'</a></h3><div class="author">'.h($b['nume_autor']).'</div><div class="price">'.number_format((float)$b['pret'],2,',','.').' lei</div></article>';}
?><div class="hero"><div class="eyebrow">Redescoperă lectura</div><h1>Cărți bune, într-o librărie readusă la viață.</h1><p>Un proiect din 2004 restaurat pentru web-ul de azi. Explorează catalogul, autorii și recomandările librăriei.</p></div>
<h2 class="section-title">Noutăți</h2><div class="book-grid"><?php foreach($newBooks as $b)card($b);?></div><h2 class="section-title">Cele mai populare</h2><div class="book-grid"><?php foreach($popular as $b)card($b);?></div><?php include 'page_bottom.php'; ?>
